def observable(phrase,note,needs):
 return {'template_id':template_id,'phrase':phrase,'note':note,'status':'draft','observable_requirements':{'observables':[{'name':n,'unit':u,'description':d} for n,u,d in needs], 'context_inputs':[], 'sweep_dimensions':[{'name':'other_traffic_spacing','unit':'m','description':'Physical setup distance for coverage sampling.'}], 'landmarks':[], 'recording_needs':[{'name':n,'unit':u,'description':d} for n,u,d in needs], 'limitations':['Original physical measurements do not define the legal judgment.']}}
write('judgment_safety',observable('reasonable safety','No statutory numeric safety cutoff.',[('reverse_displacement_m','m','Measured reverse motion.'),('other_traffic_center_distance_m','m','Measured center separation; body clearance needs separate review.')]))
